import fs from 'fs';
import path from 'path';
import { z } from 'zod';
import { randomUUID } from 'crypto';
import { serverRuntimeDirectory } from './serverHandshake';
import type { AttachedServer } from './client';
import { RIVET_VERSION } from '../config/telemetry';
import { writeFileAtomicSync } from '../utils/writeFileAtomic';

const interruptionSchema = z.object({
  receiptPath: z.string(),
  serverVersion: z.string().nullable(),
  clientVersion: z.string(),
  createdAt: z.string(),
  workIds: z.array(z.string()),
  message: z.string(),
});
export type RuntimeInterruption = z.infer<typeof interruptionSchema>;

const interruptionDirectory = (projectPath: string): string =>
  path.join(serverRuntimeDirectory(projectPath), 'interruptions');

const collectWorkIds = (value: unknown): string[] => {
  if (Array.isArray(value)) return value.flatMap(collectWorkIds);
  if (!value || typeof value !== 'object') return [];
  if (
    'status' in value &&
    ['succeeded', 'failed', 'cancelled'].includes(String(value.status))
  )
    return 'refinement' in value ? collectWorkIds(value.refinement) : [];
  return Object.entries(value).flatMap(([key, item]) => {
    if (
      ['workId', 'workItemId', 'requestId', 'agentRunId', 'traceId'].includes(
        key,
      ) &&
      typeof item === 'string'
    )
      return [item];
    return collectWorkIds(item);
  });
};

export const recordRuntimeInterruption = ({
  attached,
  snapshot,
}: {
  attached: AttachedServer;
  snapshot: unknown;
}): RuntimeInterruption => {
  const directory = interruptionDirectory(attached.handshake.projectPath);
  fs.mkdirSync(directory, { recursive: true, mode: 0o700 });
  const receiptPath = path.join(directory, `${randomUUID()}.json`);
  const interruption: RuntimeInterruption = {
    receiptPath,
    serverVersion: attached.handshake.rivetVersion ?? null,
    clientVersion: RIVET_VERSION,
    createdAt: new Date().toISOString(),
    workIds: Array.from(new Set(collectWorkIds(snapshot))),
    message:
      'Rivet interrupted this work to upgrade its server. Restart the original request with the updated CLI. Saved completed directions remain in history; the previous session and leases no longer apply.',
  };
  writeFileAtomicSync(
    receiptPath,
    JSON.stringify({ ...interruption, snapshot }),
    { mode: 0o600 },
  );
  return interruption;
};

export const readRuntimeInterruptions = (
  projectPath: string,
): RuntimeInterruption[] => {
  const directory = interruptionDirectory(projectPath);
  if (!fs.existsSync(directory)) return [];
  return fs
    .readdirSync(directory)
    .filter((name) => name.endsWith('.json'))
    .map((name) =>
      interruptionSchema.parse(
        JSON.parse(fs.readFileSync(path.join(directory, name), 'utf8')),
      ),
    );
};
